      "replace": "def is_genai_span(span: ReadableSpan) -> bool:
    """Return whether the span has any ``gen_ai.*`` semantic convention attribute.

    Accepts both string and UTF-8‑encoded byte keys.
    """
    if span.attributes is None:
        return False

    def _key_starts_genai(key: object) -> bool:
        if isinstance(key, str):
            return key.startswith("gen_ai.")
        if isinstance(key, (bytes, bytearray)):
            try:
                decoded = key.decode("utf-8", errors="ignore")
            except Exception:
                return False
            return decoded.startswith("gen_ai.")
        return False

    return any(_key_starts_genai(key) for key in span.attributes.keys())"
