  "test": "from types import SimpleNamespace
from typing import Any, Optional

import pytest

from langfuse._client.span_filter import is_genai_span


def _make_span(*, scope_name: Optional[str] = None, attributes: Optional[dict[Any, Any]] = None):
    scope = None if scope_name is None else SimpleNamespace(name=scope_name)
    return SimpleNamespace(instrumentation_scope=scope, attributes=attributes)


def test_is_genai_span_with_byte_key():
    """Byte keys that decode to ``gen_ai.`` should be recognized as genai attributes."""
    span = _make_span(attributes={b"gen_ai.request.model": "gpt-4"})
    assert is_genai_span(span) is True


def test_is_genai_span_with_non_genai_byte_key():
    """Byte keys not starting with ``gen_ai.`` should not trigger genai detection."""
    span = _make_span(attributes={b"other.prefix": "value"})
    assert is_genai_span(span) is False


def test_is_genai_span_mixed_keys():
    """Mixed string and byte keys should work correctly."""
    span = _make_span(attributes={"gen_ai.usage.input_tokens": 10, b"gen_ai.output": "ok"})
    assert is_genai_span(span) is True"
}
